using System.Windows;namespace LexCityLauncher;public partial class SettingsWindow:Window{readonly Config C;public SettingsWindow(Config c){InitializeComponent();C=c;HostBox.Text=c.Host;PortBox.Text=c.Port.ToString();DiscordBox.Text=c.Discord;}void Save_Click(object s,RoutedEventArgs e){if(!int.TryParse(PortBox.Text,out var p)||p<1||p>65535){MessageBox.Show("Porta inválida.");return;}C.Host=HostBox.Text.Trim();C.Port=p;C.Discord=DiscordBox.Text.Trim();DialogResult=true;Close();}void Cancel_Click(object s,RoutedEventArgs e){DialogResult=false;Close();}}
